import{_ as a,H as e,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"09 | 全面调教：让GPT理解“否定”","description":"","frontmatter":{},"headers":[{"level":2,"title":"GPT 无法有效理解“否定”的根源是什么？","slug":"gpt-无法有效理解-否定-的根源是什么","link":"#gpt-无法有效理解-否定-的根源是什么","children":[]},{"level":2,"title":"在案例中学习：全面调教，设计一个长图裁剪脚本","slug":"在案例中学习-全面调教-设计一个长图裁剪脚本","link":"#在案例中学习-全面调教-设计一个长图裁剪脚本","children":[{"level":3,"title":"自检，排除自相矛盾","slug":"自检-排除自相矛盾","link":"#自检-排除自相矛盾","children":[]},{"level":3,"title":"一步一步实现","slug":"一步一步实现","link":"#一步一步实现","children":[]},{"level":3,"title":"彩蛋：图片嵌入和流程图","slug":"彩蛋-图片嵌入和流程图","link":"#彩蛋-图片嵌入和流程图","children":[]},{"level":3,"title":"图片嵌入：“要你好看”","slug":"图片嵌入-要你好看","link":"#图片嵌入-要你好看","children":[]},{"level":3,"title":"流程图：先胜后战，全局在握","slug":"流程图-先胜后战-全局在握","link":"#流程图-先胜后战-全局在握","children":[]}]},{"level":2,"title":"小黑板","slug":"小黑板","link":"#小黑板","children":[]},{"level":2,"title":"踏浪扬帆","slug":"踏浪扬帆","link":"#踏浪扬帆","children":[]},{"level":2,"title":"附｜Script Master","slug":"附-script-master","link":"#附-script-master","children":[]}],"relativePath":"零基础GPT应用入门课/09｜全面调教：让GPT理解“否定”.md","filePath":"零基础GPT应用入门课/09｜全面调教：让GPT理解“否定”.md","lastUpdated":1795561467000}'),p={name:"零基础GPT应用入门课/09｜全面调教：让GPT理解“否定”.md"};function i(l,s,o,c,h,g){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="_09-全面调教-让gpt理解-否定" tabindex="-1">09 | 全面调教：让GPT理解“否定” <a class="header-anchor" href="#_09-全面调教-让gpt理解-否定" aria-label="Permalink to &quot;09 | 全面调教：让GPT理解“否定”&quot;">​</a></h1><p>你好，我是键盘，我们继续驯服 GPT。</p><p>这节课我们来直面“人智协作”中绕不开的底层诉求——精准控制。什么意思呢？它可以拆解成两个子课题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/1.png" alt=""></a></p><ol><li><p>要：清晰、明确地表达你的需求。</p></li><li><p>不要：引导 AI 规避你不想生成的内容。</p></li></ol><p>大多数人都盯着“要什么”，却忽略了“精准地不要什么”的重要性，结果就是因为这 20% 的细节，让 80% 的结果可用性大幅下降。这就是课程标题中“让 GPT 理解否定”的含义了。</p><p>其实在 GPT 这类语言模型中遇到的“控制”难题到了非文本生成模型中也无法回避。比如Midjourney，它的出图质量那么高，为什么大家花了钱还在愁落地应用呢？Stable Diffusion +ControlNet 会告诉你，是控制。ControlNet 插件就是直接指挥 SD 应该用什么表情、什么角度、什么姿势等等细节来绘图的。控制效果不好，消耗更多的成本，也足够让你质疑 AI、怀疑人生。</p><p>这节课我会带你设计一个脚本人设来实现长图的自动切割，通过案例讲明白如何让 GPT 理解“否定”。这个脚本在商品详情页的裁剪、图片邮件切割等等这类图片切割的场景里都非常实用。</p><p>我们需要用到 Mac 自带的 AppleScript，Windows 用户使用 Python 也可以替代实现。如果你会使用 Figma，也可以让 ChatGPT 帮助开发一个插件来实现。</p><p>以上方案都不需要开发基础，我会把它们作为分支功能合入 prompt，和你一起通通实现。</p><h2 id="gpt-无法有效理解-否定-的根源是什么" tabindex="-1">GPT 无法有效理解“否定”的根源是什么？ <a class="header-anchor" href="#gpt-无法有效理解-否定-的根源是什么" aria-label="Permalink to &quot;GPT 无法有效理解“否定”的根源是什么？&quot;">​</a></h2><p>GPT 模型是基于概率和模式来识别 prompt 的，而不是通过真正的阅读来理解文本。所以 TA可能无法准确地理解和处理否定概念。但它的性能和准确度会随着模型的更新和优化而提高。另一方面，GPT 会通过提取重点关键字来进一步理解 prompt。</p><p>这里面，具体的关键词权重最高，连接词和“不要”这样的表达可能会被忽略。</p><p>在咱们课程的留言区中，叶筱结合自己的理解，给出了生动的比喻。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/2.png" alt=""></a></p><ul><li>叶筱的留言</li></ul><p>再比如我们讲过的“双语混打”中爬取 Twitter 数据的案例，GPT 会更倾向于使用相关的 API来实现，偏偏我还在 prompt 中提到了 API，那 TA 就会盯着 API 关键词，忽略“不要使用”四个大字。</p><ul><li>案例 prompt</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写一个python脚本，将Twitter的&lt;​post&gt;抓取后保存为pdf，不要使用Twitter API。</span></span></code></pre></div><p>也就是说，在这种模式下，GPT 更大概率会使用 API 来实现，而不是你说什么就是什么。使用“不要”换成“Do not”这种双语混打策略都不能彻底解决“有效否定”的原因也在这里。</p><p>下面是官方实践给出的佐证和指导，可以参考。</p><ul><li><p>Instead of just saying what not to do, say what to do instead。（用肯定来取代否定）</p></li><li><p>❌ Less effective（效果不佳）</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The following is a conversation between an Agent and a Customer. DO NOT ASK USERN</span></span>
<span class="line"><span>Customer: I can’t log in to my account.</span></span>
<span class="line"><span>Agent:</span></span></code></pre></div><ul><li>✅ Better（效果更好）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The following is a conversation between an Agent and a Customer. The agent will a</span></span>
<span class="line"><span>Customer: I can’t log in to my account.</span></span>
<span class="line"><span>Agent:</span></span></code></pre></div><h2 id="在案例中学习-全面调教-设计一个长图裁剪脚本" tabindex="-1">在案例中学习：全面调教，设计一个长图裁剪脚本 <a class="header-anchor" href="#在案例中学习-全面调教-设计一个长图裁剪脚本" aria-label="Permalink to &quot;在案例中学习：全面调教，设计一个长图裁剪脚本&quot;">​</a></h2><p>上面的官方指导我在第二节课的“有效否定三策略”中也有讲过，再复习一下。</p><ol><li><p>否定转肯定。</p></li><li><p>侧重肯定，再附上对应的否定。</p></li><li><p>加入示例调教。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现在你可以借助综合人设模版，直接通过展开 /功能：要做什么 来盘点需求，同步设计</span></span></code></pre></div><p>prompt，看看怎么针对综合人设的 5 个重点定义，把“有效否定 3 策略”融合进去。</p><p>为了方便理解，你可以先把“肯定 / 否定”这一组概念，扩展为要 / 不要、偏好 / 默认、是 / 不是、应该 / 避免……因为它们和“肯定 / 否定”一样，都隐藏了一个判断的逻辑。</p><ul><li>功能：要做什么，不要什么。</li></ul><p>开局先用一句话定义核心功能，围绕核心来有序展开细节，你的设计就不会乱。</p><ul><li>prompt 设计：核心功能</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>功能：针对指定路径的长图，按一个指定高度切割为多个切片，宽度不变，新建桌面文件夹Slices保存</span></span></code></pre></div><p>这里我还命名了一个综合人设“Script Master”，可以容纳不同平台和编程语言的解决方案。另外，“任务完成”这种关键的反馈也设置一下，让 GPT 设计好 UI，而且可以精准控制差异化，比如 Mac 上用弹窗、Python 的是文字反馈、Figma 则是完整 GUI（图形用户界面）。除了这些实际功能，还有洗脑用的“初始化”，让 GPT 先和用户打招呼，递出菜单沟通需求。</p><ul><li>prompt 设计：子功能</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/mac：用AppleScript编写一个脚本来实现，\`格式选择\`需要UI</span></span>
<span class="line"><span>/win：编写一个python脚本来实现</span></span>
<span class="line"><span>/figma：开发一个Figma插件来实现，需要UI</span></span>
<span class="line"><span>/help：列出\`偏好\`菜单，提供指引</span></span></code></pre></div><ul><li>prompt 设计：初始化</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始化：{\`回复\`+\`配图\`+\`偏好\`列表+\`指令\`表格……}</span></span></code></pre></div><ul><li>偏好：偏好什么，否则默认什么。</li></ul><p>GPT 理解偏好的语境还是很容易的，侧重肯定你的偏好即可。没有想法就默认使用一套设计好的高容错默认值。</p><p>比如你日常用的是 Windows，初始 prompt 里的平台默认值就改成 Windows。这些偏好会决定 GPT 用什么设置来接收什么任务，用什么样的方式去执行。注意，偏好不是焊死的，随时可以用 /help 指令来调整。</p><ul><li>可复用的 prompt 写法</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🎛️ 基础：&lt;用户基础&gt; 默认：小白</span></span></code></pre></div><ul><li>判断：满足条件做什么，否则做什么。</li></ul><p>这是让 GPT 一步一步思考的关键。</p><p>先说情况判断。与其一条路走到黑，让 GPT 不停地执行所有事情，不如设计多个分支，某个节点满足条件再自动推理下一个分支，会更加精准、高效。“一条道走到黑”是没有判断的，即使出错也可能最后再给你反馈。就像地上一个井盖丢了，就应该先树立一个警示牌，而不是等人掉进去了再说“哦欧……”。</p><p>举个例子，如果想达到的效果是：假如用户定位是“小白”，则提供必要的安装指引再开始设计；如果用户有一定基础，则直接给出代码，不要给多余的指引。那应该怎么写呢？</p><ul><li>可复用的 prompt 判断示例</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果用户是“小白”，请直接提供方案。否则：</span></span>
<span class="line"><span>- 选择/win的情况，你应该先引导用户安装python、安装依赖包。</span></span>
<span class="line"><span>- 选择/figma插件的情况，你应该提供详尽的指导。</span></span></code></pre></div><p>还有一种判断是确认类判断，“是”就继续，“不是”就修改。我倾向于用“# 注释”的方式来调教GPT。比如“不要使用代码块回复”即遇到 Markdown 就正确地渲染出来。</p><p>另外，假如用户已经修改了某个参数，确认过了，那么根据“偏好只确认一次”，就不要再麻烦用户继续确认其他的设置，直接进入主题就好。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#不要使用代码块回复，偏好只确认一次</span></span></code></pre></div><p>如果前面已经提供了“偏好”，那就按需修改，不然就扣 1 默认，进入主题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请确认你的偏好，回“1”保持默认。</span></span></code></pre></div><ul><li>模版：什么输出格式？拒绝单调。</li></ul><p>模版就是所谓的示例调教，让 GPT 抄作业。通过这种方式，直截了当地说清楚 GPT 应该做什么。注意不要使用干巴巴的纯文字段落，要用咱们说过的结构化表达。</p><ul><li>可复用的 prompt 写法</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表格输出\`偏好\`，模版：</span></span>
<span class="line"><span>## ✦偏好✦</span></span>
<span class="line"><span>表格 #不要使用序号</span></span>
<span class="line"><span>用列表列出\`指令\`菜单，模版：</span></span>
<span class="line"><span>## ✦指令✦</span></span></code></pre></div><p>不同的分支，可以有不同的模版，比如设置项适合用带图标的表格，指令菜单适合用列表，表格序号是冗余可以去掉。这些差异性和颗粒度都能通过自然语言精准控制。</p><ul><li>要求：应该怎样，避免怎样。</li></ul><p>因为要求是影响全局的，所以描述就要更加缜密，重点应用“先肯定，再附上对应的否定”，把“要”和“不要”都带上。在这个案例里，最重要的事情是强调“把用户提供的信息自动填入设计的代码中”，不要让人来操心。剩下的做到高效、简洁易懂和少冗余，把必要的要求用“肯定”的语气表达出来就足够了。</p><ul><li>可复用的 prompt 写法</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 把用户提供的路径填入脚本，而不是人力整合。</span></span>
<span class="line"><span>- 使用高效的算法，避免复杂的运算和步骤。</span></span>
<span class="line"><span>- 尽量少地调用依赖库存，使用简洁易懂的注释，而不是包含大量术语的方式。</span></span>
<span class="line"><span>- 正确渲染markdown。</span></span>
<span class="line"><span>- 请一步一步思考，输出完整的代码。</span></span></code></pre></div><p>最后，在综合人设 prompt（模板在这里）的设计中梳理需求，全盘控制。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/3.png" alt=""></a></p><p>可以看到，在“有效否定 3 策略”的基础上，这里使用了更全面的控制，其中有 2 点最重要。</p><ol><li><p>加入判断，应对复杂。通过设计多个任务节点的方式，有效释放 GPT 思维链（CoT）的能力，一步一步推理，而且是有针对性地选择某个任务节点来继续。</p></li><li><p>增加上下文联系，让描述模式更好理解。比如“使用高效的方式”和“避免额外的引用库”这样的上下文组合。比在某些位置单纯提到“不要什么”更精准，不需要处处添加示例。</p></li></ol><h3 id="自检-排除自相矛盾" tabindex="-1">自检，排除自相矛盾 <a class="header-anchor" href="#自检-排除自相矛盾" aria-label="Permalink to &quot;自检，排除自相矛盾&quot;">​</a></h3><p>跑机之前，先过一遍整体的描述有没有自相矛盾的地方。因为多综合人设容易突破 500 字，前后不一致的概率就更大。比如前文要求“不要使用序号”，后面又来一句“序号列居中对齐”。如果出现这种低级错误，一定要修正初始 prompt 后再继续。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/4.png" alt=""></a></p><ul><li>做好自检</li></ul><p>一切就绪，我们放飞 ChatGPT 对话框的小飞机。</p><h3 id="一步一步实现" tabindex="-1">一步一步实现 <a class="header-anchor" href="#一步一步实现" aria-label="Permalink to &quot;一步一步实现&quot;">​</a></h3><p>首先和 GPT 沟通偏好。通过 emoji 加表格菜单的方式就能打造友好的 UI 交互。这里的图片裁切任务，宽度不变，单独要求高度使用 1456px。根据“只确认一次”的要求，我们就可以直接选择不同场景的指令开始派活。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/5.png" alt=""></a></p><ul><li>偏好确认</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一种场景，选择 /mac ，用 AppleScript 来实现。这里发现需要额外的 ImageMagick 支</span></span></code></pre></div><p>持，粘贴代码运行就好。接着拿到 AppleScript 代码，依旧是复制粘贴，想不想夸 GPT 就随你了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/6.png" alt=""></a></p><p>一稿过，既高效又有效。路径和参数都自动合入到了代码里，也按要求给出了提醒 UI，完全不需要我们懂编码，也不需要操作图像处理工具。可以看到，这里如无意外，最重要的反而是</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“完成的反馈”，我在  提醒 中给出了偏好设置。</span></span></code></pre></div><p>那有意外怎么办呢？老办法，用 prompt 模版 报错：你复制的报错信息 。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/7.png" alt=""></a></p><ul><li>参数无需人工填入，无报错，顺利执行</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二种场景，切到 /win ，验收 Windows 用户使用 Python 来实现的情况，也一稿通过了</span></span></code></pre></div><p>（设计师泪流满面)。依赖库只使用了图形处理所需的 PIL 和访问系统的 os，没有多余。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/8.png" alt=""></a></p><ul><li>给出 Python 安装指引和实现方案</li></ul><p>这里的命名不是严格遵循“偏好”的，其实对于复杂的任务，局部不稳定输出还是比较常见的。只要不影响核心的功能，通过上一节课的迭代方法持续沟通修正就好，这里就只要指正一次。</p><p>成果顺利验收。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/9.png" alt=""></a></p><ul><li>Python 方案顺利执行（此处未修改命名方式）</li></ul><p>到这里已经跑了 2 个方案，输出有点长了，很多小伙伴输出一长就会迷路。没关系，一句</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/help 就能解决。除了切换需求，你也可以随时修改偏好。除此之外的其他疑问，GPT 都会</span></span></code></pre></div><p>为你排忧解难。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/10.png" alt=""></a></p><ul><li>随时提供帮助</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第三个场景，切到 /figma ，用（指挥 GPT）开发一个插件的方式来实现。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/11.png" alt=""></a></p><ul><li>“开发”一个 Figma 插件</li></ul><p>Figma 插件这个方式主打 GUI 可视化交互，需要比较长的迭代沟通，这里我用设计师小伙伴Kakitchen 实现的成品给你感受一下。现在在 GPT 的协助下，一位设计师就可以秒变全栈工程师。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/12.png" alt=""></a></p><ul><li>做一个 Figma 插件来裁剪</li></ul><h3 id="彩蛋-图片嵌入和流程图" tabindex="-1">彩蛋：图片嵌入和流程图 <a class="header-anchor" href="#彩蛋-图片嵌入和流程图" aria-label="Permalink to &quot;彩蛋：图片嵌入和流程图&quot;">​</a></h3><p>案例到这里就结束了，不过除了迭代答案，我们当然也迭代知识，在这次实验里我有 2 个关于定义专业输出的新发现，和你分享一下，分别是精准控制图片嵌入和流程图生成（控制逻辑）。</p><h3 id="图片嵌入-要你好看" tabindex="-1">图片嵌入：“要你好看” <a class="header-anchor" href="#图片嵌入-要你好看" aria-label="Permalink to &quot;图片嵌入：“要你好看”&quot;">​</a></h3><p>偏好设置中的配图来自可商用的高质量图库 Unsplash。在 GPT 中使用图片，除了必要的数据可视化和图形辅助学习，装饰类的都不适合占太大篇幅，尤其是高度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/13.png" alt=""></a></p><ul><li>把握图片的合适高度</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据原图 URL 中的参数 &amp;fit=crop&amp;w=1974 ，可以看出自适应方式是裁剪，宽度是</span></span></code></pre></div><p>1974px。如果你已经有一个选好的 unsplash 图片的链接，那就用这行 Markdown 模版嵌入图片。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>![接口配图](https://source.unsplash.com/目标宽度x目标高度/?&lt;关键词&gt;)</span></span></code></pre></div><p>不想动手找图片，那就用之前分享过的翻盲盒接口，这种方式不能控制目标图片，它会随着浏览器的刷新，根据关键词来变换输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>![接口配图](https://source.unsplash.com/目标宽度x目标高度/?&lt;关键词&gt;)</span></span></code></pre></div><h3 id="流程图-先胜后战-全局在握" tabindex="-1">流程图：先胜后战，全局在握 <a class="header-anchor" href="#流程图-先胜后战-全局在握" aria-label="Permalink to &quot;流程图：先胜后战，全局在握&quot;">​</a></h3><p>假如你还想用可视化的方式清晰地还原设计逻辑，通过这种方式来自检或者细化设计，怎么办？</p><ul><li>prompt</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>将xx流程输出为mermaid代码</span></span></code></pre></div><p>用上面的 prompt，再找一个支持 Mermaid 的编辑器，把 GPT 生成的代码贴进去，节点中的emoji 和符号（比如“?” ）会造成报错，去掉即可。这里我用了 Notion 笔记，看右图成果，哪里需要自己动手画？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/14.png" alt=""></a></p><ul><li>还原 GPT “一步一步思考”的路径</li></ul><h2 id="小黑板" tabindex="-1">小黑板 <a class="header-anchor" href="#小黑板" aria-label="Permalink to &quot;小黑板&quot;">​</a></h2><p>这节课，我从“人智协作”中绕不开的底层诉求出发，将精准控制拆解成了“要”和“不要”两个子课题，“要”的问题前面的课程已经解决了，所以我们集火解决掌控“不要”的问题。</p><p>GPT 无法有效理解“否定”，主要源于 TA 是根据概率和模式来识别，而不是通过真正的阅读来理解文本的基础逻辑。另一方面，GPT 通过提取重点关键字来实现进一步操作，“不要”这样的动作可能会被忽略。所以，我们可以通过融合“有效否定 3 策略”“加入判断”和“增加上下文联系”等多种策略来保证 GPT 能够真正“阅读理解”。</p><p>比如我们这节课设计的 Script Master，在“/ 功能”中明确要做什么、不要什么，而不是只说要什么；在“偏好”中侧重肯定个人偏好，否则就用默认值容错，无需示例；再加入“判断”，满足条件做什么，否则做什么，精准控制实现路径和方法；使用“模版”示例调教，让 GPT 抄作业；最后列出“要求”，说一说应该怎样，避免怎样。</p><p>整体 prompt 的设计也加入了上下文联系的方法来减少冗余表达或者多余的示例。在用不同方式实现长图自动裁剪的案例中，我们掌握了让 GPT 真正理解“否定”的方法，有效地掌控全局。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/15.png" alt=""></a></p><ul><li>GPT 无法有效理解“否定”的根源</li></ul><p>彩蛋环节，我分享了灵活控制嵌入图片尺寸的方法，还有使用 mermaid 代码一键生成流程图来还原设计逻辑的方法。它们在日常的 GPT 工作流中还大有可为，记得多多尝试。</p><p>其实这个方案一开始是受小伙伴的 Figma 插件思路启发的，我探索了其他几种不同实现方式之后才整合成一个综合方案。GPT 的学习之路，很多志同道合的朋友都在互相启发，希望这种“携手共进”的方式也能给你学习灵感。</p><p>这套课程中，我们不仅要系统掌握利用 GPT 解决问题的基本规律，对于具体的问题，还要刨根问底，这样才能将有限的方法变成可以无限迁移的方法论。</p><p>要点：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/09/16.png" alt=""></a></p><h2 id="踏浪扬帆" tabindex="-1">踏浪扬帆 <a class="header-anchor" href="#踏浪扬帆" aria-label="Permalink to &quot;踏浪扬帆&quot;">​</a></h2><p>超级个体的时代已经来临，你可以大胆做很多以前不敢想的事情了。尝试用同样的思路处理垃圾邮件、通讯录或者零散的记事本。通过智能删减，让自己更轻松。</p><p>测试验收前，记得备份好重要的信息哦。</p><p>期待在评论区看到你的思考或感受分享，也欢迎你将这节课分享给感兴趣的朋友们，戳此加入课程交流群，我们下节课再会。</p><h2 id="附-script-master" tabindex="-1">附｜Script Master <a class="header-anchor" href="#附-script-master" aria-label="Permalink to &quot;附｜Script Master&quot;">​</a></h2><p>兼容：ChatGPT，建议去掉配图来释放占用的字数。</p><p>效果更佳：GPT-4</p><p>插件：不需要</p><p>字数：480</p><p>声明：本人设仅供个人学习体验，未经许可不得商用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个计算机脚本设计专家，请根据下面的说明，确认用户偏好之后，实现[一个长图切割脚本设计]</span></span>
<span class="line"><span>功能：针对指定路径的长图 {替换你的长图路径}，按一个指定高度切割为多个切片，宽度不变，新建桌面文件</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>1、初始化：{\`回复\`+\`配图\`+\`偏好\`列表+\`指令\`表格。 #不要使用代码块回复，偏好只确认一次</span></span>
<span class="line"><span>- 回复：“**Hi I’m Script Maser,请确认你的偏好，回“1”保持默认。**</span></span>
<span class="line"><span>偏好示例：平台：Win</span></span>
<span class="line"><span>”</span></span>
<span class="line"><span>- ![配图](https://images.unsplash.com/photo-1516670428252-df97bba108d1?ixlib=rb-4.</span></span>
<span class="line"><span>- 表格输出\`偏好\`，模版：</span></span>
<span class="line"><span>## ✦偏好✦</span></span>
<span class="line"><span>表格 #不要使用序号</span></span>
<span class="line"><span>- 用列表列出\`指令\`菜单，模版：</span></span>
<span class="line"><span>## ✦指令✦</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>2、偏好：</span></span>
<span class="line"><span>🎛️ 基础：&lt;用户基础&gt; 默认：小白</span></span>
<span class="line"><span>💻 平台：&lt;​Win&gt; 默认：Mac</span></span>
<span class="line"><span> 提醒：&lt;定义代码中的完成提示&gt; 默认：“🎉 任务已完成”</span></span>
<span class="line"><span>🏞️ 格式：&lt;​jpg&gt; 默认：png</span></span>
<span class="line"><span>📝 命名：&lt;切片命名&gt; 默认：原图名称_s_count</span></span>
<span class="line"><span>📏 高度：&lt;切片高度&gt; 默认：750</span></span>
<span class="line"><span>3、指令：</span></span>
<span class="line"><span>/mac：用AppleScript编写一个脚本来实现，\`格式选择\`需要UI</span></span>
<span class="line"><span>/win：编写一个python脚本来实现</span></span>
<span class="line"><span>/figma：开发一个Figma插件来实现，需要UI</span></span>
<span class="line"><span>/help：列出\`偏好\`菜单，提供指引</span></span>
<span class="line"><span>4、判断：</span></span>
<span class="line"><span>如果用户是“小白”，请直接提供方案。否则：</span></span>
<span class="line"><span>- 选择/win的情况，你应该先引导用户安装python、安装依赖包。</span></span>
<span class="line"><span>- 选择/figma插件的情况，你应该提供详尽的指导。</span></span>
<span class="line"><span>5、要求：</span></span>
<span class="line"><span>- 把用户提供的路径填入脚本，而不是人力整合。</span></span>
<span class="line"><span>- 使用高效的算法，避免复杂的运算和步骤。</span></span>
<span class="line"><span>- 尽量少地调用依赖库存，使用简洁易懂的注释，而不是包含大量术语。</span></span>
<span class="line"><span>- 正确渲染markdown。</span></span>
<span class="line"><span>- 请一步一步思考，输出完整的代码。</span></span></code></pre></div>`,146)])])}const E=a(p,[["render",i]]);export{u as __pageData,E as default};
